package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch118 {
    val stories = listOf(
        StorySeries(
            id = "the_old_cinema_sound_archive",
            title = "The Old Cinema Sound Archive",
            tagline = "A student media club preserves a neighbourhood cinema's memories through interviews and careful sound editing.",
            parts = listOf(
                StoryPart(1, "The Silent Projector", listOf("The old cinema had become a community arts hall, but its entrance still displayed a faded poster from its final year as a movie theatre. A media club was invited to create an audio archive about the building's history.", "Tariq wanted to record the sound of the projector, but the machine was no longer used and could not be operated for the project.", "The hall manager suggested collecting memories from former staff and visitors instead, with permission from everyone who took part.")),
                StoryPart(2, "The Interview Plan", listOf("The students prepared questions about the building, the ticket desk, and the events people remembered. Their teacher reviewed the questions to make sure they were respectful and did not ask for private information.", "Every interviewee would be told how the recording might be used and could decline any question or withdraw permission before publication.", "Tariq created a form to record the interview date, consent, and approved use of each audio file.")),
                StoryPart(3, "A Ticket Seller's Memory", listOf("A former ticket seller remembered how the queue used to form along the pavement before weekend screenings. She described the small bell at the counter and the handwritten showtime board.", "The students recorded her story in a quiet room and played it back so she could confirm that the sound was clear.", "She approved a short excerpt for the archive and asked the students to include her role but not her personal contact details.")),
                StoryPart(4, "The Noisy Recording", listOf("Another interview included traffic noise that made several sentences difficult to understand. Tariq tried a basic edit, but the result sounded unnatural.", "The teacher explained that editing should improve clarity without changing meaning. They asked the interviewee whether she would be comfortable repeating the unclear section.", "She agreed, and the team recorded the passage again in a quieter room.")),
                StoryPart(5, "A Box of Tickets", listOf("The hall manager found a box of old ticket stubs and programmes. The students photographed them for the archive, taking care not to display names or notes that could reveal private details.", "Some dates were missing, so the club compared the programmes with public event listings and labelled uncertain dates clearly.", "The ticket seller helped identify a few designs and explained how ticket colours had changed over the years.")),
                StoryPart(6, "The Projector's Story", listOf("A retired technician visited and explained how the cinema's projection room had been arranged. He brought a public training diagram and described the work without operating any old equipment.", "The students checked the technical terms with him and recorded a short explanation of how film reels had been handled in that era.", "The archive included the diagram with its source and a note that it was a historical reference, not an operating manual.")),
                StoryPart(7, "Choosing the Sound", listOf("The club considered adding background music, but the teacher reminded them that they needed permission to use any recording they did not own.", "They chose instead to use room tone recorded by the students and a short original sound pattern made with classroom instruments.", "The simple sound design left space for the interview voices and avoided distracting from the memories.")),
                StoryPart(8, "A Listener's Correction", listOf("During a preview, an older visitor noticed that the archive placed two events in the wrong order. The students checked the dates and discovered that a programme had been filed under the wrong year.", "They corrected the sequence and thanked the visitor for pointing out the mistake. The archive included a note explaining that a date had been revised after review.", "Tariq learned that public history improved when listeners were invited to check it.")),
                StoryPart(9, "Opening Night Again", listOf("The arts hall hosted an evening where visitors could listen to selected clips and view photographs of the old ticket designs.", "The interviewees approved the final versions before the event. A printed guide explained who had contributed and how the recordings had been prepared.", "People recognised details they had not thought about in years: the shape of the counter, the handwritten board, and the pause before a show began.")),
                StoryPart(10, "A Living Archive", listOf("The media club stored the approved recordings in an organised archive with clear file names, consent records, and backup copies held by the school according to its policy.", "The hall manager invited the next class to add new interviews about the building's current role as an arts space.", "Tariq listened once more to the ticket seller's story. The cinema no longer showed films, but its voices had found a new screen: the memories people could now hear and share."))
            )
        )
    )
}
